use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let cents = input.as_i64().unwrap();
    let n = input.as_i64().unwrap();
    let mut shares = Vec::new();

    for _ in 0..n {
        let share = cents / 64;
        shares.push(share);
        cents %= 64;
    }

    Value::Array(shares.into_iter().map(|s| Value::Number(s.into())).collect())
}
